def fetch(off, size, dst):
    for att in range(4):
        try:
            hdr = urllib.request.urlopen(urllib.request.Request(URL, headers={"Range": f"bytes={off}-{off+29}"}), timeout=120).read()
            n, m = struct.unpack("<HH", hdr[26:30]); start = off + 30 + n + m
            data = urllib.request.urlopen(urllib.request.Request(URL, headers={"Range": f"bytes={start}-{start+size-1}"}), timeout=300).read()
            assert len(data) == size; open(dst, "wb").write(data); return
        except Exception as e: time.sleep(3 * (att + 1))
    raise RuntimeError("fetch failed " + dst)
def work(r):
    sid = r["sid"]; p = f"/tmp/m/{sid}.tif"
