        fetch(r["mask"][0], r["mask"][2], p)
        with tifffile.TiffFile(p) as tf:
            lv = tf.series[0].levels; shp = [tuple(l.shape[:2]) for l in lv]; j = next((k for k in range(len(lv)) if shp[k][0] * shp[k][1] <= 8e6), len(lv) - 1)
            a = lv[j].asarray(); c = np.bincount(a.ravel(), minlength=5)[:5]; f = shp[0][0] / shp[j][0]
